"""Freeze an isolated joint creator/finisher transport hypothesis before scoring."""
import hashlib,json
from pathlib import Path
R=Path('reports/player-impact-v35');O=Path('reports/player-impact-v34');sha=lambda p:hashlib.sha256(Path(p).read_bytes()).hexdigest()
files=['input.mjs','engine.mjs','probability.mjs','worker.mjs','prepare-contexts.mjs','run.mjs','validation-score.py','verify-ledgers.mjs','ovr-input.mjs']
for name in files:
 text=(O/name).read_text(encoding='utf-8').replace('reports/player-impact-v34','reports/player-impact-v35').replace('test/joint_source_opportunities.js','test/joint_creator_transport.js')
 if name=='run.mjs':
  text=text.replace("version:'joint-source-self-floor-34'","version:'joint-creator-terminal-35'")
  start=text.index("design:'");end=text.index("',hashes",start)
  text=text[:start]+"design:'Joint creator/finisher transport, no fitted coefficient: creator rows are elastic source self+pass rates normalized only to conserved terminal total; finisher columns are elastic terminal rates. Positive prior diagonal=self, off-diagonal=pass*relative received demand excluding self; multiplicative balancing permits self/pass substitution with no hard self floor/ceiling. Diagonal becomes own shooting, never an assist. Source roles/attributes and v30 probabilities unchanged; contexts recomputed on identical FGA/energy support. Four same-season reconstructions,3seeds, full/strict; archived official and v30 controls, official per-season winsMAE+0.5 gate unchanged. Report all individual/role/on-court errors and complete matched workload probe. No rank/name/onoff/win residual fit, no blind/causal claim."+text[end:]
 if name=='prepare-contexts.mjs':
  start=text.index("design:'");end=text.index("',stints",start)
  text=text[:start]+"design:'Joint creator/terminal source reconstruction: normalized source self+pass creator rows and terminal finisher columns, positive source prior balanced jointly. Self and passing can substitute; no hard role floors or ceilings. Raw attributes and roles unchanged, original actual FGA/energy support, v30 probability and dependence preserved. Same-season source descriptors contain aggregate made outcomes, not blind/causal; no fitted rank/name/win coefficient."+text[end:]
 f=R/name;assert not f.exists();f.write_text(text,encoding='utf-8')
protocol={'priorTurn':'progress: v34 complete28,023+9,600games; rejected hard source-self floor after AST/3P regression and one failed win season','hypothesis':'Joint source creator and terminal marginals, positive own/pass prior balanced without hard self cap/floor. All off-diagonal cells represent passes; diagonal is own shooting only.','fittedParameter':False,'rowDefinition':'(sourceSelf+sourcePass)*sum(sourceTerminal)/sum(sourceSelf+sourcePass), after existing frozen elastic role transform','columnDefinition':'sourceTerminal after existing frozen elastic role transform','priorDefinition':'diag sourceSelf; offdiag sourcePass_i*sourceReceive_j/sum(other sourceReceive)','adoptionGate':'Each of four seasons archived official winsMAE+0.5 plus full individual/role/on-court and workload review. No gate relaxed, no ranking-driven fit. No adoption from positive support alone.','validation':'2022-23..2025-26,3matchingseeds,full and strict. Source full-season rates contain outcomes; same-season reconstruction, no blind/causal claim.','hashes':{str(R/name).replace('\\','/'):sha(R/name) for name in files+['model.mjs','scaffold.py']}|{'test/joint_creator_transport.js':sha('test/joint_creator_transport.js')}}
(R/'mechanism-protocol.json').write_text(json.dumps(protocol,indent=2),encoding='utf-8');print('Created and froze joint-creator experiment.')
